const SYMBOLS: Record<string, { pre: string }> = { EUR: { pre: '€' }, CHF: { pre: 'CHF ' }, GBP: { pre: '£' }, USD: { pre: '$' } };
const DEFAULT_RATES: Record<string, number> = { EUR: 1, CHF: 0.94, GBP: 0.85, USD: 1.09 };

interface Prefs {
  lang: string; setLang: (l: string) => void;
  currency: string; setCurrency: (c: string) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  money: (eur: number) => string;
}

const Ctx = createContext<Prefs>(null as any);
export const usePrefs = () => useContext(Ctx);

export const PrefsProvider = ({ children }: { children: ReactNode }) => {
  const [lang, setLangState] = useState(localStorage.getItem('viara_lang') || 'en');
  const [currency, setCurrencyState] = useState(localStorage.getItem('viara_cur') || 'EUR');
  const [rates, setRates] = useState<Record<string, number>>(DEFAULT_RATES);

  useEffect(() => { api.get('/rates').then((r) => setRates(r.data)).catch(() => {}); }, []);
  useEffect(() => {
    setDateLocale(LANGS.find((l) => l.code === lang)?.locale || 'en-GB');
  }, [lang]);

  const setLang = (l: string) => { localStorage.setItem('viara_lang', l); setLangState(l); };
  const setCurrency = (c: string) => { localStorage.setItem('viara_cur', c); setCurrencyState(c); };

  const t = (key: string, params?: Record<string, string | number>) => {
    let s = S[lang]?.[key] ?? S.en[key] ?? key;
    if (params) Object.entries(params).forEach(([k, v]) => { s = s.replace(`{${k}}`, String(v)); });
    return s;
  };

  const money = (eur: number) => {
    const v = Math.round(eur * (rates[currency] ?? 1));
    return `${SYMBOLS[currency].pre}${v.toLocaleString('en-GB')}`;
  };

  return <Ctx.Provider value={{ lang, setLang, currency, setCurrency, t, money }}>{children}</Ctx.Provider>;
};
